+  onSelectDate
+}: DailySignupCountChartProps) {
+  const t = useTranslations();
+
+  if (isLoading) {
+    return (
+      <div className="h-[300px] flex items-center justify-center">
+        <p className="text-muted-foreground">{t('common.loading')}</p>
+      </div>
+    );
+  }
+
+  if (!data || data.length === 0) {
+    return (
+      <div className="h-[300px] flex items-center justify-center">
+        <p className="text-muted-foreground">
+          {t('admin.users.report.noData', {
+            defaultMessage: '所選期間沒有數據'
+          })}
+        </p>
+      </div>
+    );
+  }
+
+  return (
+    <ResponsiveContainer width="100%" height={300}>
+      <BarChart data={data} margin={{ top: 5, right: 20, left: -25, bottom: 5 }}>
+        <CartesianGrid strokeDasharray="3 3" />
+        <XAxis
+          dataKey="date"
+          tickFormatter={(tick) =>
+            new Date(tick + 'T00:00:00Z').toLocaleDateString('zh-TW', {
+              month: 'short',
+              day: 'numeric',
+              timeZone: 'UTC'
+            })
+          }
+          dy={5}
+        />
+        <YAxis allowDecimals={false} />
+        <Tooltip
+          labelFormatter={(label) =>
+            new Date(label + 'T00:00:00Z').toLocaleDateString('zh-TW', {
+              year: 'numeric',
+              month: 'long',
+              day: 'numeric',
+              timeZone: 'UTC'
+            })
+          }
+          formatter={(value: number) => [
+            value,
+            t('admin.users.report.signupCount', {
+              defaultMessage: '新增數'
+            })
+          ]}
+        />
+        <Bar
+          dataKey="count"
+          fill="#34d399"
+          name="count"
+          onClick={(bar) => {
+            const date = (bar as { payload?: { date?: unknown } } | null)?.payload
+              ?.date;
+            if (!onSelectDate || typeof date !== 'string') return;
+            onSelectDate(date);
+          }}
+        >
+          {data.map((_, index) => (
+            <Cell
+              key={`daily-signup-cell-${index}`}
+              style={{ cursor: onSelectDate ? 'pointer' : 'default' }}
+            />
+          ))}
+          <LabelList
+            dataKey="count"
+            position="top"
+            formatter={(value: number) => (value > 0 ? value : '')}
+            style={{ fontSize: '12px', fill: '#666' }}
+          />
+        </Bar>
+      </BarChart>
+    </ResponsiveContainer>
+  );
+}
