+import { NextRequest, NextResponse } from 'next/server';
+
+import createLogger from '@/lib/logger';
+import { getUsersSignedUpOnDateUtc } from '@/data/admin/user-signups';
+
+const logger = createLogger('api/admin/user-signups');
+
+function parseOptionalInt(value: string | null): number | undefined {
+  if (!value) return undefined;
+  const n = Number(value);
+  if (!Number.isFinite(n)) return undefined;
+  return Math.trunc(n);
+}
+
+export async function GET(request: NextRequest) {
+  try {
+    const { searchParams } = new URL(request.url);
+    const date = searchParams.get('date') ?? '';
+    const limit = parseOptionalInt(searchParams.get('limit'));
+    const offset = parseOptionalInt(searchParams.get('offset'));
+
+    const data = await getUsersSignedUpOnDateUtc({ date, limit, offset });
+
+    return NextResponse.json({ success: true, data });
+  } catch (error) {
+    logger.error('getUserSignupsError', {
+      error: error instanceof Error ? error : { cause: String(error) }
+    });
+
+    const message = error instanceof Error ? error.message : '';
+    const lower = message.toLowerCase();
+    const status = lower.includes('no permission') ? 403 : lower.includes('invalid') ? 400 : 500;
+
+    return NextResponse.json(
+      { success: false, error: status === 403 ? 'No permission' : message || 'Server error' },
+      { status }
+    );
+  }
+}
