+function parseUtcDateRangeFromParams(params: {
+  dateFrom?: string;
+  dateTo?: string;
+}): { from?: Date; to?: Date } {
+  const parseDateOnly = (value?: string) => {
+    if (!value) return null;
+    const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(value.trim());
+    if (!match) return null;
+    const year = Number(match[1]);
+    const month = Number(match[2]);
+    const day = Number(match[3]);
+    if (!Number.isFinite(year) || !Number.isFinite(month) || !Number.isFinite(day)) {
+      return null;
+    }
+    if (month < 1 || month > 12) return null;
+    if (day < 1 || day > 31) return null;
+    return { year, month, day };
+  };
+
+  const parseBoundary = (value: string | undefined, boundary: 'start' | 'end') => {
+    if (!value) return undefined;
+
+    // 1) YYYY-MM-DD：沿用既有行為（以 UTC 的整日範圍）
+    const parsed = parseDateOnly(value);
+    if (parsed) {
+      return boundary === 'start'
+        ? new Date(
+            Date.UTC(parsed.year, parsed.month - 1, parsed.day, 0, 0, 0, 0)
+          )
+        : new Date(
+            Date.UTC(parsed.year, parsed.month - 1, parsed.day, 23, 59, 59, 999)
+          );
+    }
+
+    // 2) 其他格式（例如 DatePickerWithTime 送來的 ISO 字串）
+    const dateTime = new Date(value);
+    if (Number.isNaN(dateTime.getTime())) return undefined;
+    return dateTime;
+  };
+
+  const from = parseBoundary(params.dateFrom, 'start');
+  const to = parseBoundary(params.dateTo, 'end');
+
+  if (from && to && from.getTime() > to.getTime()) {
+    return { from: to, to: from };
+  }
+
+  return { from, to };
+}
