+'use client';
+
+import { Users, Ticket, TrendingUp, TrendingDown } from 'lucide-react';
+import { useTranslations } from 'next-intl';
+
+import { Card, CardContent } from '@/components/ui/card';
+import { cn } from '@/lib/utils';
+import { calculateChange } from '@/utils/stats';
+import type { UserSignupStats } from '@/types/user-signup-stats';
+
+interface SignupSummaryCardProps {
+  newUsersCount: number;
+  usersWithAnyInvitationCode: number;
+  invitationCodeAdoptionRate: number;
+  isLoading?: boolean;
+  previousStats?: UserSignupStats | null;
+  isPreviousLoading?: boolean;
+}
+
+const statItems = [
+  { key: 'newUsers', icon: Users },
+  { key: 'usersWithInvitationCode', icon: Ticket },
+  { key: 'invitationCodeAdoptionRate', icon: TrendingUp }
+] as const;
+
+export function SignupSummaryCard({
+  newUsersCount,
+  usersWithAnyInvitationCode,
+  invitationCodeAdoptionRate,
+  isLoading,
+  previousStats,
+  isPreviousLoading
+}: SignupSummaryCardProps) {
+  const t = useTranslations();
+
+  if (isLoading) {
+    return (
+      <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
+        {[1, 2, 3].map((i) => (
+          <Card key={i} className="border shadow-sm">
+            <CardContent className="p-4 flex items-center justify-between text-center gap-1">
+              <div className="h-3 w-20 bg-muted rounded mb-2 animate-pulse" />
+              <div className="h-8 w-16 bg-muted rounded animate-pulse" />
+            </CardContent>
+          </Card>
+        ))}
+      </div>
+    );
+  }
+
+  const values = [newUsersCount, usersWithAnyInvitationCode, invitationCodeAdoptionRate];
+  const previousValues = previousStats
+    ? [
+        previousStats.newUsersCount,
+        previousStats.invitationCode.usersWithAny,
+        previousStats.invitationCode.adoptionRate
+      ]
+    : [undefined, undefined, undefined];
+
+  return (
+    <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
+      {statItems.map((item, index) => {
+        const value = values[index];
+        const previousValue = previousValues[index];
+        const hasChange = previousValue !== undefined && !isPreviousLoading;
+        const change = hasChange ? calculateChange(value, previousValue) : null;
+        const isPositive = change !== null && change > 0;
+        const isNegative = change !== null && change < 0;
+        const Icon = item.icon;
+
+        const displayValue =
+          item.key === 'invitationCodeAdoptionRate'
+            ? `${value.toFixed(2)}%`
+            : value.toLocaleString();
+
+        const displayPrevious =
+          previousValue === undefined
+            ? null
+            : item.key === 'invitationCodeAdoptionRate'
+            ? `${Number(previousValue).toFixed(2)}%`
+            : Number(previousValue).toLocaleString();
+
+        return (
+          <Card
+            key={item.key}
+            className="border shadow-sm hover:shadow-md transition-all"
+          >
+            <CardContent className="p-4">
