+                    defaultMessage:
+                      item.key === 'newUsers'
+                        ? '新增使用者'
+                        : item.key === 'usersWithInvitationCode'
+                        ? '有使用邀請碼的使用者'
+                        : '邀請碼使用率'
+                  })}
+                </p>
+              </div>
+              <p className="flex items-center justify-center gap-1 text-lg md:text-2xl font-bold text-center">
+                {displayValue}
+              </p>
+              <div className="flex items-center justify-center gap-2 mt-1">
+                {displayPrevious && hasChange && (
+                  <p className="text-xs text-muted-foreground text-center">
+                    {t('admin.users.report.previousPeriod', {
+                      defaultMessage: '前一期'
+                    })}
+                    : {displayPrevious}
+                  </p>
+                )}
+                {change !== null && hasChange && (
+                  <div
+                    className={cn(
+                      'flex items-center gap-1 text-xs font-medium',
+                      isPositive && 'text-emerald-600 dark:text-emerald-400',
+                      isNegative && 'text-red-600 dark:text-red-400',
+                      !isPositive && !isNegative && 'text-muted-foreground'
+                    )}
+                  >
+                    {isPositive ? (
+                      <TrendingUp className="h-3 w-3" />
+                    ) : isNegative ? (
+                      <TrendingDown className="h-3 w-3" />
+                    ) : null}
+                    <span>
+                      {change > 0 ? '+' : ''}
+                      {change.toFixed(1)}%
+                    </span>
+                  </div>
+                )}
+              </div>
+            </CardContent>
+          </Card>
+        );
+      })}
+    </div>
+  );
+}
