+import NoPermission from '@/components/admin/no-permission';
+import { checkCurrentUserPermission } from '@/data/admin/permissions';
+import { checkIsSystemAdmin } from '@/data/admin/roles';
+
+import UsersReportClient from './report-client';
+
+export default async function UsersReportPage() {
+  const [hasUserManagementPermission, isSystemAdmin] = await Promise.all([
+    checkCurrentUserPermission('write-userManagement'),
+    checkIsSystemAdmin()
+  ]);
+
+  if (!hasUserManagementPermission || !isSystemAdmin) {
+    return <NoPermission />;
+  }
+
+  return <UsersReportClient />;
+}
