+import { NextRequest, NextResponse } from 'next/server';
+
+import createLogger from '@/lib/logger';
+import { getUserSignupStats } from '@/data/user-signup-stats';
+
+const logger = createLogger('api/admin/user-signup-stats');
+
+function parseOptionalDate(value: string | null): Date | undefined {
+  if (!value) return undefined;
+  const date = new Date(value);
+  if (Number.isNaN(date.getTime())) return undefined;
+  return date;
+}
+
+export async function GET(request: NextRequest) {
+  try {
+    const { searchParams } = new URL(request.url);
+
+    const startDateRaw = searchParams.get('startDate');
+    const endDateRaw = searchParams.get('endDate');
+
+    const startDate = parseOptionalDate(startDateRaw);
+    const endDate = parseOptionalDate(endDateRaw);
+
+    if (startDateRaw && !startDate) {
+      return NextResponse.json(
+        { success: false, error: 'Invalid startDate' },
+        { status: 400 }
+      );
+    }
+    if (endDateRaw && !endDate) {
+      return NextResponse.json(
+        { success: false, error: 'Invalid endDate' },
+        { status: 400 }
+      );
+    }
+
+    const data = await getUserSignupStats({ startDate, endDate });
+
+    return NextResponse.json({ success: true, data });
+  } catch (error) {
+    logger.error('getUserSignupStatsError', {
+      error: error instanceof Error ? error : { cause: String(error) }
+    });
+
+    const message = error instanceof Error ? error.message : '';
+    const status = message.toLowerCase().includes('no permission') ? 403 : 500;
+
+    return NextResponse.json(
+      { success: false, error: status === 403 ? 'No permission' : 'Server error' },
+      { status }
+    );
+  }
+}
