+'use server';
+
+import { Prisma } from '@prisma/client';
+
+import prisma from '@/lib/prisma';
+import createLogger from '@/lib/logger';
+import { checkCurrentUserPermission } from '@/data/admin/permissions';
+import { checkIsSystemAdmin } from '@/data/admin/roles';
+
+const logger = createLogger('data/admin/user-signups');
+
+function parseUtcDateOnly(value: string): { year: number; month: number; day: number } | null {
+  const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(value.trim());
+  if (!match) return null;
+  const year = Number(match[1]);
+  const month = Number(match[2]);
+  const day = Number(match[3]);
+  if (!Number.isFinite(year) || !Number.isFinite(month) || !Number.isFinite(day)) {
+    return null;
+  }
+  if (month < 1 || month > 12) return null;
+  if (day < 1 || day > 31) return null;
+  return { year, month, day };
+}
+
+export type UserSignupRow = {
+  id: string;
+  name: string | null;
+  email: string | null;
+  image: string | null;
+  createdAt: Date;
+  invitationCode: string | null;
+  invitationCodeRedeemedAt: Date | null;
+};
+
+export async function getUsersSignedUpOnDateUtc(params: {
+  date: string; // YYYY-MM-DD
+  limit?: number;
+  offset?: number;
+}): Promise<{ date: string; total: number; users: UserSignupRow[]; limit: number; offset: number; hasMore: boolean }> {
+  const [hasPermission, isSystemAdmin] = await Promise.all([
+    checkCurrentUserPermission('write-userManagement'),
+    checkIsSystemAdmin()
+  ]);
+
+  if (!hasPermission || !isSystemAdmin) {
+    throw new Error('No permission to access user signup list');
+  }
+
+  const parsed = parseUtcDateOnly(params.date);
+  if (!parsed) {
+    throw new Error('Invalid date');
+  }
+
+  const limit = Math.min(Math.max(params.limit ?? 200, 1), 500);
+  const offset = Math.max(params.offset ?? 0, 0);
+
+  const from = new Date(Date.UTC(parsed.year, parsed.month - 1, parsed.day, 0, 0, 0, 0));
+  const to = new Date(Date.UTC(parsed.year, parsed.month - 1, parsed.day, 23, 59, 59, 999));
+
+  try {
+    const [total, baseUsers] = await Promise.all([
+      prisma.user.count({
+        where: { createdAt: { gte: from, lte: to } }
+      }),
+      prisma.user.findMany({
+        where: { createdAt: { gte: from, lte: to } },
+        select: { id: true, name: true, email: true, image: true, createdAt: true },
+        orderBy: { createdAt: 'asc' },
+        skip: offset,
+        take: limit
+      })
+    ]);
+
+    const userIds = baseUsers.map((u) => u.id);
+
+    type FirstRedemptionRow = { userId: string; code: string; redeemedAt: Date };
+    const redemptionRows = userIds.length
+      ? await prisma.$queryRaw<FirstRedemptionRow[]>`
+          SELECT DISTINCT ON (icr."userId")
+            icr."userId" AS "userId",
+            ic.code AS "code",
+            icr."redeemedAt" AS "redeemedAt"
+          FROM "public"."InvitationCodeRedemption" icr
+          INNER JOIN "public"."InvitationCode" ic
+            ON ic.id = icr."invitationCodeId"
+          WHERE icr."userId" IN (${Prisma.join(userIds)})
+          ORDER BY icr."userId", icr."redeemedAt" ASC;
+        `
+      : [];
+
+    const firstRedemptionByUserId = new Map(
+      redemptionRows.map((row) => [row.userId, { code: row.code, redeemedAt: row.redeemedAt }])
+    );
+
+    const users: UserSignupRow[] = baseUsers.map((u) => ({
+      ...u,
+      invitationCode: firstRedemptionByUserId.get(u.id)?.code ?? null,
+      invitationCodeRedeemedAt: firstRedemptionByUserId.get(u.id)?.redeemedAt ?? null
+    }));
+
+    return {
+      date: params.date,
+      total,
+      users,
+      limit,
+      offset,
+      hasMore: offset + users.length < total
+    };
+  } catch (error) {
+    logger.error('getUsersSignedUpOnDateUtcError', {
+      error: error instanceof Error ? error : { cause: String(error) },
+      date: params.date
+    });
+    throw error;
+  }
+}
+
