diff --git a/data/user-signup-stats.ts b/data/user-signup-stats.ts
new file mode 100644
index 0000000..dc2488a
--- /dev/null
+++ b/data/user-signup-stats.ts
@@ -0,0 +1,343 @@
+'use server';
+
+import { Prisma } from '@prisma/client';
+
+import prisma from '@/lib/prisma';
+import createLogger from '@/lib/logger';
+import { checkCurrentUserPermission } from '@/data/admin/permissions';
+import { checkIsSystemAdmin } from '@/data/admin/roles';
+import type { UserSignupStats } from '@/types/user-signup-stats';
+
+const logger = createLogger('data/user-signup-stats');
+
+export type { UserSignupStats } from '@/types/user-signup-stats';
+
+function calculateRate(value: number, total: number): number {
+  if (!total) return 0;
+  return Math.round((value / total) * 100 * 100) / 100;
+}
+
+export async function getUserSignupStats({
+  startDate,
+  endDate
+}: {
+  startDate?: Date;
+  endDate?: Date;
+}): Promise<UserSignupStats> {
+  const [hasPermission, isSystemAdmin] = await Promise.all([
+    checkCurrentUserPermission('write-userManagement'),
+    checkIsSystemAdmin()
+  ]);
+
+  if (!hasPermission || !isSystemAdmin) {
+    throw new Error('No permission to access user signup stats');
+  }
+
+  const fromDate = startDate ? new Date(startDate) : null;
+  if (fromDate) {
+    fromDate.setHours(0, 0, 0, 0);
+  }
+  const toDate = endDate ? new Date(endDate) : null;
+  if (toDate) {
+    toDate.setHours(23, 59, 59, 999);
+  }
+
+  const cohortCte = Prisma.sql`
+    WITH cohort AS (
+      SELECT u.id, u."createdAt"
+      FROM "public"."User" u
+      WHERE 1=1
+        ${fromDate ? Prisma.sql`AND u."createdAt" >= ${fromDate}` : Prisma.empty}
+        ${toDate ? Prisma.sql`AND u."createdAt" <= ${toDate}` : Prisma.empty}
+    )
+  `;
+
+  try {
+    type DailyRow = { date: Date; count: bigint };
+    type CountRow = { count: bigint };
+    type InvitationTotalsRow = {
+      total_redemptions: bigint;
+      users_with_any: bigint;
+    };
+    type InvitationDistributionRow = {
+      invitationCodeId: string;
+      code: string;
+      redemptionCount: bigint;
+    };
+    type GenerationCountsRow = {
+      users_with_image: bigint;
+      users_with_video: bigint;
+      users_with_any: bigint;
+    };
+    type GenerationTotalsRow = {
+      image_generation_requests: bigint;
+      image_generated_images: bigint | null;
+      video_generation_requests: bigint;
+      video_generated_outputs: bigint;
+    };
+    type AiToolUsageRow = {
+      aiToolId: string;
+      aiToolName: string | null;
+      imageCount: bigint;
+      videoCount: bigint;
+      totalCount: bigint;
+    };
+    type BaseModelRow = {
+      baseModelId: string | null;
+      baseModelName: string | null;
+      count: bigint;
+    };
+
+    const [
+      dailyRows,
+      newUsersCountRow,
+      invitationTotalsRow,
+      invitationDistributionRows,
+      generationAllTimeRow,
+      generationTotalsRow,
+      aiToolUsageRows,
+      baseModelRows
+    ] = await Promise.all([
+      prisma.$queryRaw<DailyRow[]>`
+        ${cohortCte}
+        SELECT
+          DATE_TRUNC('day', c."createdAt") AS date,
+          COUNT(*) AS count
+        FROM cohort c
+        GROUP BY date
+        ORDER BY date ASC;
+      `,
+      prisma.$queryRaw<CountRow[]>`
+        ${cohortCte}
+        SELECT COUNT(*) AS count
+        FROM cohort;
+      `,
+      prisma.$queryRaw<InvitationTotalsRow[]>`
+        ${cohortCte}
+        SELECT
+          COUNT(icr.id) AS total_redemptions,
+          COUNT(DISTINCT icr."userId") AS users_with_any
+        FROM cohort c
+        LEFT JOIN "public"."InvitationCodeRedemption" icr
+          ON icr."userId" = c.id;
+      `,
+      prisma.$queryRaw<InvitationDistributionRow[]>`
+        ${cohortCte}
+        , first_redemption AS (
+          SELECT DISTINCT ON (icr."userId")
+            icr."userId" AS user_id,
+            icr."invitationCodeId" AS invitation_code_id
+          FROM cohort c
+          INNER JOIN "public"."InvitationCodeRedemption" icr
+            ON icr."userId" = c.id
+          ORDER BY icr."userId", icr."redeemedAt" ASC
+        )
+        SELECT
+          ic.id AS "invitationCodeId",
+          ic.code AS "code",
+          COUNT(*) AS "redemptionCount"
+        FROM first_redemption fr
+        INNER JOIN "public"."InvitationCode" ic
+          ON fr.invitation_code_id = ic.id
+        GROUP BY ic.id, ic.code
+        ORDER BY "redemptionCount" DESC
+        LIMIT 50;
+      `,
+      prisma.$queryRaw<GenerationCountsRow[]>`
+        ${cohortCte}
+        SELECT
+          (
+            SELECT COUNT(DISTINCT ig."userId")
+            FROM "public"."ImageGeneration" ig
+            INNER JOIN cohort c ON ig."userId" = c.id
+          ) AS users_with_image,
+          (
+            SELECT COUNT(DISTINCT ivr."userId")
+            FROM "public"."ImageToVideoRequest" ivr
+            INNER JOIN cohort c ON ivr."userId" = c.id
+            INNER JOIN "public"."VideoRequestOutput" vro ON vro."requestId" = ivr.id
+          ) AS users_with_video,
+          (
+            SELECT COUNT(DISTINCT x.user_id)
+            FROM (
+              SELECT ig."userId" AS user_id
+              FROM "public"."ImageGeneration" ig
+              INNER JOIN cohort c ON ig."userId" = c.id
+              UNION
+              SELECT ivr."userId" AS user_id
+              FROM "public"."ImageToVideoRequest" ivr
+              INNER JOIN cohort c ON ivr."userId" = c.id
+              INNER JOIN "public"."VideoRequestOutput" vro ON vro."requestId" = ivr.id
+            ) x
+          ) AS users_with_any;
+      `,
+      prisma.$queryRaw<GenerationTotalsRow[]>`
+        ${cohortCte}
+        SELECT
+          (
+            SELECT COUNT(*)
+            FROM "public"."ImageGeneration" ig
+            INNER JOIN cohort c ON ig."userId" = c.id
+          ) AS image_generation_requests,
+          (
+            SELECT SUM(COALESCE(ig."batchSize", 1))
+            FROM "public"."ImageGeneration" ig
+            INNER JOIN cohort c ON ig."userId" = c.id
+          ) AS image_generated_images,
+          (
+            SELECT COUNT(*)
+            FROM "public"."ImageToVideoRequest" ivr
+            INNER JOIN cohort c ON ivr."userId" = c.id
+          ) AS video_generation_requests,
+          (
+            SELECT COUNT(*)
+            FROM "public"."VideoRequestOutput" vro
+            INNER JOIN "public"."ImageToVideoRequest" ivr
+              ON vro."requestId" = ivr.id
+            INNER JOIN cohort c ON ivr."userId" = c.id
+          ) AS video_generated_outputs;
+      `,
+      prisma.$queryRaw<AiToolUsageRow[]>`
+        WITH cohort AS (
+          SELECT u.id, u."createdAt"
+          FROM "public"."User" u
+          WHERE 1=1
+            ${fromDate ? Prisma.sql`AND u."createdAt" >= ${fromDate}` : Prisma.empty}
+            ${toDate ? Prisma.sql`AND u."createdAt" <= ${toDate}` : Prisma.empty}
+        ),
+        image_counts AS (
+          SELECT
+            ig."aiToolId" AS ai_tool_id,
+            COUNT(DISTINCT ig.id) AS image_count
+          FROM "public"."ImageGeneration" ig
+          INNER JOIN cohort c ON ig."userId" = c.id
+          WHERE ig."aiToolId" IS NOT NULL
+          GROUP BY ig."aiToolId"
+        ),
+        video_counts AS (
+          SELECT
+            ivr."aiToolId" AS ai_tool_id,
+            COUNT(DISTINCT ivr.id) AS video_count
+          FROM "public"."ImageToVideoRequest" ivr
+          INNER JOIN cohort c ON ivr."userId" = c.id
+          WHERE ivr."aiToolId" IS NOT NULL
+          GROUP BY ivr."aiToolId"
+        ),
+        merged AS (
+          SELECT
+            COALESCE(i.ai_tool_id, v.ai_tool_id) AS ai_tool_id,
+            COALESCE(i.image_count, 0) AS image_count,
+            COALESCE(v.video_count, 0) AS video_count,
+            COALESCE(i.image_count, 0) + COALESCE(v.video_count, 0) AS total_count
+          FROM image_counts i
+          FULL OUTER JOIN video_counts v ON v.ai_tool_id = i.ai_tool_id
+        )
+        SELECT
+          m.ai_tool_id AS "aiToolId",
+          COALESCE(at.name, 'Unknown') AS "aiToolName",
+          m.image_count AS "imageCount",
+          m.video_count AS "videoCount",
+          m.total_count AS "totalCount"
+        FROM merged m
+        LEFT JOIN "public"."AiTool" at ON at.id = m.ai_tool_id
+        ORDER BY "totalCount" DESC
+        ;
+      `,
+      prisma.$queryRaw<BaseModelRow[]>`
+        ${cohortCte}
+        SELECT
+          COALESCE(bm.id, 'unknown') AS "baseModelId",
+          COALESCE(bm.name, ig."baseModel", 'unknown') AS "baseModelName",
+          SUM(COALESCE(ig."batchSize", 1)) AS count
+        FROM "public"."ImageGeneration" ig
+        INNER JOIN cohort c ON ig."userId" = c.id
+        LEFT JOIN "public"."BaseModel" bm ON ig."generatedByBaseModelId" = bm.id
+        GROUP BY COALESCE(bm.id, 'unknown'), COALESCE(bm.name, ig."baseModel", 'unknown')
+        ORDER BY count DESC
+        LIMIT 20;
+      `
+    ]);
+
+    const newUsersCount = newUsersCountRow[0]?.count
+      ? Number(newUsersCountRow[0].count)
+      : 0;
+
+    const invitationTotals = invitationTotalsRow[0] || {
+      total_redemptions: BigInt(0),
+      users_with_any: BigInt(0)
+    };
+    const totalRedemptions = Number(invitationTotals.total_redemptions);
+    const usersWithAnyInvitationCode = Number(invitationTotals.users_with_any);
+
+    const allTimeCounts = generationAllTimeRow[0] || {
+      users_with_image: BigInt(0),
+      users_with_video: BigInt(0),
+      users_with_any: BigInt(0)
+    };
+    const totals = generationTotalsRow[0] || {
+      image_generation_requests: BigInt(0),
+      image_generated_images: BigInt(0),
+      video_generation_requests: BigInt(0),
+      video_generated_outputs: BigInt(0)
+    };
+
+    return {
+      dailySignups: dailyRows.map((row) => ({
+        date: new Date(row.date).toISOString().split('T')[0],
+        count: Number(row.count)
+      })),
+      newUsersCount,
+      invitationCode: {
+        totalRedemptions,
+        usersWithAny: usersWithAnyInvitationCode,
+        adoptionRate: calculateRate(usersWithAnyInvitationCode, newUsersCount),
+        distribution: invitationDistributionRows.map((row) => ({
+          invitationCodeId: row.invitationCodeId,
+          code: row.code,
+          redemptionCount: Number(row.redemptionCount)
+        }))
+      },
+      generation: {
+        allTime: {
+          usersWithImageGeneration: Number(allTimeCounts.users_with_image),
+          usersWithVideoGeneration: Number(allTimeCounts.users_with_video),
+          usersWithAnyGeneration: Number(allTimeCounts.users_with_any),
+          imageGenerationRequests: Number(totals.image_generation_requests),
+          imageGeneratedImages: Number(totals.image_generated_images ?? BigInt(0)),
+          videoGenerationRequests: Number(totals.video_generation_requests),
+          videoGeneratedOutputs: Number(totals.video_generated_outputs),
+          rateImage: calculateRate(
+            Number(allTimeCounts.users_with_image),
+            newUsersCount
+          ),
+          rateVideo: calculateRate(
+            Number(allTimeCounts.users_with_video),
+            newUsersCount
+          ),
+          rateAny: calculateRate(
+            Number(allTimeCounts.users_with_any),
+            newUsersCount
+          )
+        }
+      },
+      aiToolUsageDistribution: aiToolUsageRows.map((row) => ({
+        aiToolId: row.aiToolId,
+        aiToolName: row.aiToolName || 'Unknown',
+        imageCount: Number(row.imageCount),
+        videoCount: Number(row.videoCount),
+        totalCount: Number(row.totalCount)
+      })),
+      baseModelDistribution: baseModelRows.map((row) => ({
+        baseModelId: row.baseModelId || 'unknown',
+        baseModelName: row.baseModelName || 'unknown',
+        count: Number(row.count)
+      }))
+    };
+  } catch (error) {
+    logger.error('Error fetching user signup stats', {
+      error: error instanceof Error ? error : { cause: String(error) }
+    });
+    throw error;
+  }
+}
